<?php
declare(strict_types=1);namespace Joomleague\Module\Eventranking\Site\Helper;defined('_JEXEC')or die;
use Joomla\CMS\Factory;use Joomla\Database\DatabaseInterface;use Joomla\Registry\Registry;use Joomleague\Component\Joomleague\Domain\Service\EventRankingReader;
final class EventrankingHelper{/** @return array<string,mixed> */public function getRanking(Registry$p):array{$id=(int)$p->get('project_id',0);if($id<1)return['error'=>'MOD_JOOMLEAGUE_EVENTRANKING_NO_PROJECT'];Factory::getApplication()->bootComponent('com_joomleague');$l=Factory::getLanguage();$l->load('com_joomleague',JPATH_SITE)||$l->load('com_joomleague',JPATH_SITE.'/components/com_joomleague');try{$display=DisplayOptions::from($p);$options=['strict_code'=>true,'include_images'=>$display['show_images']];foreach(['stage_id'=>0,'date_from'=>'','date_until'=>'','participant_kind'=>'any','direction'=>'desc','ties'=>'ordinal']as$key=>$default)$options[$key]=$p->get($key,$default);$code=trim((string)$p->get('event_code',''))?:null;$ranking=(new EventRankingReader(Factory::getContainer()->get(DatabaseInterface::class)))->forProject($id,$code,min(100,max(1,(int)$p->get('limit',5))),Factory::getApplication()->getIdentity()->getAuthorisedViewLevels(),$options);if($display['show_images'])foreach($ranking['rows']as$row){$kind=$row->target_kind==='person'?'person':($row->target_kind==='team'?'team':'');$row->image=\Joomleague\Component\Joomleague\Site\Service\MediaResolver::image($kind,$row->image_path??null);}return$ranking;}catch (\Throwable $moduleFailure) { \Joomla\CMS\Log\Log::add('mod_joomleague_eventranking failure: ' . get_debug_type($moduleFailure), \Joomla\CMS\Log\Log::WARNING, 'com_joomleague.modules');return['error'=>'MOD_JOOMLEAGUE_EVENTRANKING_UNAVAILABLE'];}}}
